diff --git a/tests/fefo.test.js b/tests/fefo.test.js
new file mode 100644
index 0000000..2117d14
--- /dev/null
+++ b/tests/fefo.test.js
@@ -0,0 +1,35 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { consume } from "../src/domain/batches.js";
+import { app, fresh } from "./helpers.js";
+
+const at = "2026-10-28T10:00:00Z";
+
+test("cooking bechamel uses milk expiring tomorrow (HD-1022) before newer milk (HD-1026)", async () => {
+  const { handle, store } = app();
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 10 } });
+  assert.equal(res.status, 200);
+  const milkUsed = res.body.used.find((u) => u.itemId === 2);
+  assert.deepEqual(milkUsed.batches, [{ batchId: 4, qty: 2 }]);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1022").qty, 0);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 8);
+});
+
+test("consume follows FEFO, then receivedOn, then id, with non-expiring batches last", () => {
+  const store = fresh();
+  store.data.batches = store.data.batches.filter((b) => b.itemId !== 2);
+  store.data.batches.push(
+    { id: 20, itemId: 2, lot: "NO-EXP-LATE", qty: 1, receivedOn: "2026-10-25", expires: null, location: "fridge" },
+    { id: 21, itemId: 2, lot: "NO-EXP-EARLY", qty: 1, receivedOn: "2026-10-20", expires: null, location: "fridge" },
+    { id: 22, itemId: 2, lot: "EXP-LATER", qty: 1, receivedOn: "2026-10-19", expires: "2026-11-05", location: "fridge" },
+    { id: 25, itemId: 2, lot: "SAME-EXP-SAME-REC-HI", qty: 1, receivedOn: "2026-10-21", expires: "2026-10-30", location: "fridge" },
+    { id: 23, itemId: 2, lot: "SAME-EXP-LATE-REC", qty: 1, receivedOn: "2026-10-23", expires: "2026-10-30", location: "fridge" },
+    { id: 24, itemId: 2, lot: "SAME-EXP-SAME-REC-LO", qty: 1, receivedOn: "2026-10-21", expires: "2026-10-30", location: "fridge" },
+    { id: 26, itemId: 2, lot: "EXP-SOONEST", qty: 1, receivedOn: "2026-10-27", expires: "2026-10-29", location: "fridge" },
+  );
+  const used = consume(store, 2, 7, { at, ref: "fefo" });
+  assert.deepEqual(
+    used.map((u) => u.batchId),
+    [26, 24, 25, 23, 22, 21, 20],
+  );
+});
